function finiteTokenCount(value){const n=Number(value);return Number.isFinite(n)&&n>=0?n:null}
function formatTokenCount(value){const n=finiteTokenCount(value);if(n===null)return'—';try{return new Intl.NumberFormat(state.lang==='zh'?'zh-CN':'en-US').format(n)}catch{return String(n)}}
