function openNewThreadModal(){state.newThreadResolver=null;$('newThreadError').textContent='';$('newThreadCwd').value=state.currentThread?.cwd||state.meta?.workspace||'';$('newThreadModal').classList.remove('hidden');$('newThreadModal').setAttribute('aria-hidden','false');requestAnimationFrame(()=>$('newThreadCwd').focus())}
