async function steerPrompt(text,attachments){if(!state.currentThread?.id||!state.activeTurnId)return;if(!hasRequest('turn/steer')){toast(tr('noSteerSupport'),'warning');return}if(state.steeringBusy)return;const threadId=state.currentThread.id,expectedTurnId=state.activeTurnId;state.steeringBusy=true;state.queuedDirections+=1;$('send').disabled=true;updateStatus();try{await ensureThreadLoaded(threadId);optimisticUser(text,attachments,'steer');await rpc('turn/steer',{threadId,expectedTurnId,input:buildTurnInput(text,attachments),clientUserMessageId:`web-steer-${Date.now()}`});clearComposer();toast(tr('queuedDirection'))}catch(e){toast(`${tr('sendFailed')}: ${e.message}`,'error')}finally{state.queuedDirections=Math.max(0,state.queuedDirections-1);state.steeringBusy=false;$('send').disabled=false;updateStatus()}}
