function updateTurnHeaderState(turnId,active){const block=$('timeline')?.querySelector('[data-turn-id="'+CSS.escape(String(turnId||''))+'"]'),header=block?.querySelector('.turn-header');if(!header)return;const title=header.querySelector('.turn-header-title'),stateNode=header.querySelector('.turn-header-state');if(title)title.textContent=active?tr('turnActive'):tr('processed');if(stateNode){stateNode.textContent=active?tr('workInProgress'):tr('turnComplete');stateNode.className=`turn-header-state ${active?'active':'completed'}`}}
