function setupDrawerResize(){const panel=$('protocolPanel'),handle=$('protocolResize');if(!panel||!handle)return;const saved=Number(localStorage.getItem('cweb_drawer_width'));if(Number.isFinite(saved)&&saved>0)setDrawerWidth(saved);let startX=0,startWidth=0,activePointer=null;const stop=()=>{document.body.classList.remove('drawer-resizing');if(activePointer!==null&&handle.hasPointerCapture?.(activePointer))handle.releasePointerCapture(activePointer);activePointer=null};handle.addEventListener('pointerdown',e=>{if(window.innerWidth<=760)return;activePointer=e.pointerId;startX=e.clientX;startWidth=panel.getBoundingClientRect().width;handle.setPointerCapture?.(e.pointerId);document.body.classList.add('drawer-resizing');e.preventDefault()});handle.addEventListener('pointermove',e=>{if(activePointer===null)return;setDrawerWidth(startWidth+startX-e.clientX)});handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop);handle.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){setDrawerWidth(panel.getBoundingClientRect().width-32);e.preventDefault()}if(e.key==='ArrowRight'){setDrawerWidth(panel.getBoundingClientRect().width+32);e.preventDefault()}if(e.key==='Home'){setDrawerWidth(320);e.preventDefault()}if(e.key==='End'){setDrawerWidth(920);e.preventDefault()}})}
